-- T10: observations never establish identity authority. All export sources stay private.
grant create on schema api,app_private to git_tutor_commands;
create table app_private.crm_contact_observations(id uuid primary key default gen_random_uuid(),learner_id uuid not null references app_private.learners(id),channel text not null check(channel in('email','phone')),destination text not null,evidence_note text not null,actor_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now());
create index crm_contact_lookup on app_private.crm_contact_observations(channel,destination,learner_id);
create table app_private.crm_identity_matches(id uuid primary key default gen_random_uuid(),left_learner_id uuid not null references app_private.learners(id),right_learner_id uuid not null references app_private.learners(id),channel text not null,destination text not null,state text not null default 'pending' check(state in('pending','distinct','aliased')),version integer not null default 1,created_at timestamptz not null default now(),check(left_learner_id<right_learner_id),unique(left_learner_id,right_learner_id,channel,destination));
create table app_private.crm_identity_reviews(id uuid primary key default gen_random_uuid(),match_id uuid not null references app_private.crm_identity_matches(id),mapping_version integer not null,decision text not null check(decision in('distinct','aliased')),canonical_person_id uuid references app_private.people(id),evidence_note text not null,actor_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now(),unique(match_id,mapping_version),check((decision='aliased')=(canonical_person_id is not null)));
create function api.record_customer_contact(p_learner_id uuid,p_channel text,p_destination text,p_evidence_note text,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();ctx jsonb;normalized text;v integer;observation uuid:=gen_random_uuid();begin
 if not app_private.crm_can_access(actor,p_learner_id)then raise exception 'NOT_FOUND';end if;
 if p_channel is null or p_channel not in('email','phone')or p_destination is null or length(p_destination)>320 or p_evidence_note is null or length(btrim(p_evidence_note))not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
 normalized:=case when p_channel='email' then lower(btrim(p_destination))else regexp_replace(btrim(p_destination),'[ ()-]','','g')end;
 if(p_channel='email'and normalized!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')or(p_channel='phone'and normalized!~'^\+[1-9][0-9]{7,14}$')then raise exception 'VALIDATION_ERROR';end if;
 ctx:=app_private.booking_begin(actor,'record_customer_contact',jsonb_build_object('learner_id',p_learner_id,'channel',p_channel,'destination',p_destination,'evidence_note',p_evidence_note,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_channel||':'||normalized,0));insert into app_private.crm_customers(learner_id)values(p_learner_id)on conflict do nothing;select version into v from app_private.crm_customers where learner_id=p_learner_id for update;if v is distinct from p_expected_version then raise exception 'VERSION_CONFLICT';end if;
 insert into app_private.crm_contact_observations(id,learner_id,channel,destination,evidence_note,actor_id)values(observation,p_learner_id,p_channel,normalized,btrim(p_evidence_note),actor);
 insert into app_private.crm_identity_matches(left_learner_id,right_learner_id,channel,destination)select least(p_learner_id,c.learner_id),greatest(p_learner_id,c.learner_id),p_channel,normalized from app_private.crm_contact_observations c where c.learner_id<>p_learner_id and c.channel=p_channel and c.destination=normalized group by c.learner_id on conflict do nothing;
 update app_private.crm_customers set version=version+1 where learner_id=p_learner_id;
 return app_private.booking_finish(ctx,p_learner_id,v+1,jsonb_build_object('contact_observation_id',observation),'customer_contact_observed',jsonb_build_object('learner_id',p_learner_id));end$$;
create function api.list_customer_contacts(p_learner_id uuid,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin
 if not app_private.crm_can_access(actor,p_learner_id)then raise exception 'NOT_FOUND';end if;if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into items from(select c.id,jsonb_build_object('contact_observation_id',c.id,'channel',c.channel,'destination',c.destination,'verified',false,'created_at',c.created_at)item from app_private.crm_contact_observations c where c.learner_id=p_learner_id and(p_cursor is null or c.id>p_cursor)order by c.id limit p_limit)x;return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'contact_observation_id'else null end);end$$;
create function api.list_identity_matches(p_learner_id uuid default null,p_state text default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin
 perform app_private.require_role(actor,'admin');if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('pending','distinct','aliased'))then raise exception 'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into items from(select m.id,jsonb_build_object('match_id',m.id,'left_learner',jsonb_build_object('learner_id',l.id,'person_id',l.person_id,'display_name',lp.display_name),'right_learner',jsonb_build_object('learner_id',r.id,'person_id',r.person_id,'display_name',rp.display_name),'masked_contact',case when m.channel='email'then left(m.destination,1)||'***@'||split_part(m.destination,'@',2)else '***'||right(m.destination,4)end,'state',m.state,'version',m.version,'created_at',m.created_at)item from app_private.crm_identity_matches m join app_private.learners l on l.id=m.left_learner_id join app_private.people lp on lp.id=l.person_id join app_private.learners r on r.id=m.right_learner_id join app_private.people rp on rp.id=r.person_id where(p_learner_id is null or p_learner_id in(m.left_learner_id,m.right_learner_id))and(p_state is null or m.state=p_state)and(p_cursor is null or m.id>p_cursor)order by m.id limit p_limit)x;return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'match_id'else null end);end$$;
create function api.review_identity_match(p_match_id uuid,p_decision text,p_person_id uuid,p_evidence_note text,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;m app_private.crm_identity_matches%rowtype;begin
 perform app_private.require_role(actor,'admin');select * into m from app_private.crm_identity_matches where id=p_match_id for update;if m.id is null then raise exception 'NOT_FOUND';end if;
 ctx:=app_private.booking_begin(actor,'review_identity_match',jsonb_build_object('match_id',p_match_id,'decision',p_decision,'person_id',p_person_id,'evidence_note',p_evidence_note,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if m.version is distinct from p_expected_version then raise exception 'VERSION_CONFLICT';end if;if p_decision is null or p_decision not in('distinct','aliased')or p_evidence_note is null or length(btrim(p_evidence_note))not between 1 and 2000 or(p_decision='distinct'and p_person_id is not null)or(p_decision='aliased'and(p_person_id is null or not exists(select 1 from app_private.learners where id in(m.left_learner_id,m.right_learner_id)and person_id=p_person_id)))then raise exception 'VALIDATION_ERROR';end if;
 insert into app_private.crm_identity_reviews(match_id,mapping_version,decision,canonical_person_id,evidence_note,actor_id)values(m.id,m.version,p_decision,p_person_id,btrim(p_evidence_note),actor);update app_private.crm_identity_matches set state=p_decision,version=version+1 where id=m.id;
 return app_private.booking_finish(ctx,m.id,m.version+1,jsonb_build_object('mapping_version',m.version),'identity_match_reviewed',jsonb_build_object('match_id',m.id,'decision',p_decision));end$$;
create function app_private.crm_session_dto(p_occurrence uuid)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('occurrence_id',o.id,'title',s.title,'start_at',o.start_at,'end_at',o.end_at,'state',o.state,'format',o.format,'tutor_id',o.tutor_id,'learner_count',(select count(*)from app_private.enrollments e where e.occurrence_id=o.id),'customer_tuition_minor',finance_private.finance_json_total((select coalesce(sum((finance_private.finance_charge_balance(c.id)->>'commercial_net_minor')::numeric),0)from app_private.enrollments e join finance_private.charges c on c.enrollment_id=e.id where e.occurrence_id=o.id)),'currency','EGP')from app_private.occurrences o join app_private.offers f on f.id=o.offer_id join app_private.subjects s on s.id=f.subject_id where o.id=p_occurrence$$;
create function api.list_crm_sessions(p_from timestamptz default null,p_to timestamptz default null,p_state text default null,p_tutor_id uuid default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin
 perform app_private.require_role(actor,'admin');if p_limit is null or p_limit not between 1 and 100 or(p_from is not null and not isfinite(p_from))or(p_to is not null and not isfinite(p_to))or p_from>=p_to or(p_state is not null and p_state not in('draft','forming','confirmed','in_progress','completion_pending','completed','cancelled'))then raise exception 'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into items from(select o.id,app_private.crm_session_dto(o.id)item from app_private.occurrences o where(p_from is null or o.start_at>=p_from)and(p_to is null or o.start_at<p_to)and(p_state is null or o.state=p_state)and(p_tutor_id is null or o.tutor_id=p_tutor_id)and(p_cursor is null or o.id>p_cursor)order by o.id limit p_limit)x;return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'occurrence_id'else null end);end$$;

create table app_private.export_jobs(id uuid primary key default gen_random_uuid(),requester_id uuid not null references app_private.accounts(id),session_id uuid not null,kind text not null check(kind in('own_account','own_tutor_statement','admin_customers','admin_sessions','admin_finance')),filters jsonb not null,columns text[] not null,grain text not null,snapshot_at timestamptz not null default transaction_timestamp(),as_of timestamptz not null,row_count integer not null check(row_count between 0 and 10000),expires_at timestamptz not null default now()+interval '24 hours',created_at timestamptz not null default now());
create table app_private.export_rows(export_id uuid not null references app_private.export_jobs(id),ordinal integer not null,row_data jsonb not null,primary key(export_id,ordinal));
create table app_private.export_states(export_id uuid primary key references app_private.export_jobs(id),state text not null default 'queued'check(state in('queued','generating','ready','failed')),version integer not null default 1,job_id uuid references app_private.outbox_jobs(id),object_key text not null unique default 'exports/'||gen_random_uuid()::text,size_bytes integer,checksum_sha256 text,safe_error_code text);
create table app_private.export_download_tickets(id uuid primary key default gen_random_uuid(),export_id uuid not null references app_private.export_jobs(id),actor_id uuid not null references app_private.accounts(id),session_id uuid not null,expires_at timestamptz not null default now()+interval '5 minutes',created_at timestamptz not null default now());
create table app_private.export_access_events(id uuid primary key default gen_random_uuid(),export_id uuid,actor_id uuid,allowed boolean not null,stage text not null,created_at timestamptz not null default now());
create function app_private.export_columns(p_kind text)returns text[] language sql immutable set search_path='' as $$select case p_kind
 when 'own_account'then array['learner_id','display_name','enrollment_id','occurrence_id','start_at','state','customer_charge_minor','allocated_cash_minor','balance_minor','currency']
 when 'own_tutor_statement'then array['earning_id','occurrence_id','source_type','earned_minor','adjustment_minor','net_earned_minor','settled_minor','reserved_minor','owed_minor','available_minor','currency','effective_at']
 when 'admin_customers'then array['learner_id','account_id','display_name','email','archived','balance_minor','currency']
 when 'admin_sessions'then array['occurrence_id','title','start_at','end_at','state','format','tutor_id','learner_count','tuition_total_minor','tutor_fee_minor','currency']
 when 'admin_finance'then array['allocation_id','transfer_id','payer_account_id','charge_id','learner_id','enrollment_id','occurrence_id','amount_minor','reversed_minor','net_allocated_minor','currency','effective_at']end$$;
create function app_private.export_assert_scope(p_actor uuid,p_session uuid,p_kind text,p_filters jsonb,p_columns text[])returns void language plpgsql security definer set search_path='' as $$declare learner uuid;begin
 if not app_private.auth_session_active(p_actor,p_session)or not app_private.payment_verified_account(p_actor)then raise exception 'SESSION_REVOKED';end if;
 if p_kind like 'admin_%'then perform app_private.require_role(p_actor,'admin');
 elsif p_kind='own_tutor_statement'then perform app_private.require_role(p_actor,'tutor');if not exists(select 1 from app_private.tutors where account_id=p_actor)then raise exception 'NOT_FOUND';end if;
 elsif p_kind='own_account'then
 for learner in select value::uuid from jsonb_array_elements_text(p_filters->'learner_ids')loop
 if p_columns&&array['learner_id','display_name']then perform app_private.assert_learner_scope(p_actor,learner,'profile',false);end if;
 if p_columns&&array['enrollment_id','occurrence_id','start_at','state']then perform app_private.assert_learner_scope(p_actor,learner,'booking',false);end if;
 if p_columns&&array['customer_charge_minor','allocated_cash_minor','balance_minor','currency']then perform app_private.assert_learner_scope(p_actor,learner,'payments',false);end if;
 end loop;
 else raise exception 'VALIDATION_ERROR';end if;end$$;
-- Financial cutoff is posting time. Identity and schedule fields are the materialization snapshot.
create function app_private.export_charge(p_charge uuid,p_as_of timestamptz)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('customer_charge_minor',finance_private.finance_json_total(coalesce(c.amount_minor,0)+coalesce((select sum(a.signed_minor)from finance_private.charge_adjustments a where a.charge_id=c.id and a.recorded_at<=p_as_of),0)),'allocated_cash_minor',finance_private.finance_json_total(coalesce((select -sum(l.signed_minor)from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where l.charge_id=c.id and l.account_code='receivable'and t.source_type in('payment_allocation','allocation_reversal')and t.recorded_at<=p_as_of),0)),'balance_minor',finance_private.finance_json_total(coalesce((select sum(l.signed_minor)from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where l.charge_id=c.id and l.account_code='receivable'and t.recorded_at<=p_as_of),0)))from(select 1)x left join finance_private.charges c on c.id=p_charge and c.created_at<=p_as_of$$;
create function api.request_export(p_kind text,p_filters jsonb,p_columns text[],p_as_of timestamptz,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' set default_transaction_isolation='repeatable read' as $$
declare actor uuid:=app_private.require_actor();session_id uuid:=(current_setting('request.jwt.claims',true)::jsonb->>'session_id')::uuid;ctx jsonb;eid uuid:=gen_random_uuid();job uuid;rows jsonb;item jsonb;grain text;allowed text[];from_at timestamptz;to_at timestamptz;selected uuid[];count_rows integer;begin
 if current_setting('transaction_isolation')<>'repeatable read'then raise exception 'DEPENDENCY_UNAVAILABLE';end if;
 if app_private.export_columns(p_kind)is null or p_filters is null or jsonb_typeof(p_filters)<>'object'or p_columns is null or cardinality(p_columns)not between 1 and 30 or array_position(p_columns,null)is not null or not p_columns<@app_private.export_columns(p_kind)or cardinality(p_columns)<>(select count(distinct c)from unnest(p_columns)c)then raise exception 'VALIDATION_ERROR';end if;
 allowed:=case p_kind when'own_account'then array['learner_ids','from','to']when'own_tutor_statement'then array['from','to']when'admin_customers'then array['q','archived']when'admin_sessions'then array['from','to','state','tutor_id']when'admin_finance'then array['from','to','learner_ids']end;
 if exists(select 1 from jsonb_each(p_filters)x where not x.key=any(allowed)or x.value='null'::jsonb)then raise exception 'VALIDATION_ERROR';end if;
 if p_as_of is null or not isfinite(p_as_of)or p_as_of>now()+interval '5 seconds'or p_as_of<timestamptz'0001-01-01+00'then raise exception 'INVALID_TIME';end if;
 begin from_at:=(p_filters->>'from')::timestamptz;to_at:=(p_filters->>'to')::timestamptz;
 if p_filters?'learner_ids'then if jsonb_typeof(p_filters->'learner_ids')<>'array'then raise exception 'VALIDATION_ERROR';end if;select array_agg(value::uuid)into selected from jsonb_array_elements_text(p_filters->'learner_ids');if cardinality(selected)not between 1 and 100 or selected is null or cardinality(selected)<>(select count(distinct x)from unnest(selected)x)then raise exception 'VALIDATION_ERROR';end if;end if;
 if p_filters?'tutor_id'then perform(p_filters->>'tutor_id')::uuid;end if;
 exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then raise exception 'VALIDATION_ERROR';end;
 if(p_kind='own_account'and selected is null)or(from_at is not null and not isfinite(from_at))or(to_at is not null and not isfinite(to_at))or from_at>=to_at or(p_filters?'q'and(jsonb_typeof(p_filters->'q')<>'string'or length(p_filters->>'q')>200))or(p_filters?'archived'and jsonb_typeof(p_filters->'archived')<>'boolean')or(p_filters?'state'and p_filters->>'state'not in('draft','forming','confirmed','in_progress','completion_pending','completed','cancelled'))then raise exception 'VALIDATION_ERROR';end if;
 if selected is not null and exists(select 1 from unnest(selected)x where not exists(select 1 from app_private.learners where id=x))then raise exception 'NOT_FOUND';end if;
 perform app_private.export_assert_scope(actor,session_id,p_kind,p_filters,p_columns);
 ctx:=app_private.booking_begin(actor,'request_export',jsonb_build_object('kind',p_kind,'filters',p_filters,'columns',p_columns,'as_of',p_as_of),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then perform set_config('response.status','202',true);return ctx->'replay_result';end if;
 if p_kind='own_account'then grain:='enrollment';
 select coalesce(jsonb_agg(x.item order by x.learner_id,x.enrollment_id),'[]'::jsonb)into rows from(select l.id learner_id,e.id enrollment_id,jsonb_build_object('learner_id',l.id,'display_name',p.display_name,'enrollment_id',e.id,'occurrence_id',o.id,'start_at',o.start_at,'state',e.state,'currency','EGP')||app_private.export_charge(c.id,p_as_of)item from app_private.learners l join app_private.people p on p.id=l.person_id left join app_private.enrollments e on e.learner_id=l.id and e.created_at<=p_as_of left join app_private.occurrences o on o.id=e.occurrence_id left join finance_private.charges c on c.enrollment_id=e.id where l.id=any(selected)and(from_at is null or o.start_at>=from_at)and(to_at is null or o.start_at<to_at)order by l.id,e.id limit 10001)x;
 elsif p_kind='admin_customers'then grain:='learner';
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into rows from(select l.id,jsonb_build_object('learner_id',l.id,'account_id',l.account_id,'display_name',p.display_name,'email',(select v.destination from app_private.verified_contacts v where v.account_id=l.account_id and v.channel='email'and v.verified_at is not null and v.revoked_at is null order by v.id limit 1),'archived',coalesce(c.archived,false),'balance_minor',finance_private.finance_json_total((select coalesce(sum((app_private.export_charge(ch.id,p_as_of)->>'balance_minor')::numeric),0)from finance_private.charges ch where ch.learner_id=l.id and ch.created_at<=p_as_of)),'currency','EGP')item from app_private.learners l join app_private.people p on p.id=l.person_id left join app_private.crm_customers c on c.learner_id=l.id where coalesce(c.archived,false)=coalesce((p_filters->>'archived')::boolean,false)and(not p_filters?'q'or p.display_name ilike '%'||(p_filters->>'q')||'%'or l.id::text=p_filters->>'q'or exists(select 1 from app_private.verified_contacts v where v.account_id=l.account_id and v.verified_at is not null and v.revoked_at is null and v.destination ilike '%'||(p_filters->>'q')||'%'))order by l.id limit 10001)x;
 elsif p_kind='admin_sessions'then grain:='occurrence';
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into rows from(select o.id,(app_private.crm_session_dto(o.id)-'customer_tuition_minor')||jsonb_build_object('learner_count',(select count(*)from app_private.enrollments e where e.occurrence_id=o.id and e.created_at<=p_as_of),'tuition_total_minor',finance_private.finance_json_total((select coalesce(sum((app_private.export_charge(c.id,p_as_of)->>'customer_charge_minor')::numeric),0)from app_private.enrollments e join finance_private.charges c on c.enrollment_id=e.id where e.occurrence_id=o.id)),'tutor_fee_minor',(select fee_minor from finance_private.tutor_fee_agreements where id=o.current_fee_agreement_id))item from app_private.occurrences o where o.created_at<=p_as_of and(from_at is null or o.start_at>=from_at)and(to_at is null or o.start_at<to_at)and(not p_filters?'state'or o.state=p_filters->>'state')and(not p_filters?'tutor_id'or o.tutor_id=(p_filters->>'tutor_id')::uuid)order by o.id limit 10001)x;
 elsif p_kind='admin_finance'then grain:='payment_allocation';
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into rows from(select a.id,jsonb_build_object('allocation_id',a.id,'transfer_id',a.transfer_id,'payer_account_id',b.payer_account_id,'charge_id',c.id,'learner_id',c.learner_id,'enrollment_id',c.enrollment_id,'occurrence_id',e.occurrence_id,'amount_minor',a.amount_minor,'reversed_minor',finance_private.finance_json_total(r.amount),'net_allocated_minor',finance_private.finance_json_total(a.amount_minor-r.amount),'currency',a.currency,'effective_at',a.effective_at)item from finance_private.payment_allocations a join finance_private.charges c on c.id=a.charge_id join finance_private.transfer_payer_bindings b on b.id=a.payer_binding_id left join app_private.enrollments e on e.id=c.enrollment_id cross join lateral(select coalesce(sum(amount_minor),0)amount from finance_private.allocation_reversals where allocation_id=a.id and recorded_at<=p_as_of)r where a.recorded_at<=p_as_of and(from_at is null or a.effective_at>=from_at)and(to_at is null or a.effective_at<to_at)and(selected is null or c.learner_id=any(selected))order by a.id limit 10001)x;
 else grain:='earning';
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into rows from(select e.id,jsonb_build_object('earning_id',e.id,'occurrence_id',e.occurrence_id,'source_type',e.source_type,'earned_minor',b->'amount_minor','adjustment_minor',b->'adjustment_minor','net_earned_minor',b->'net_minor','settled_minor',finance_private.finance_json_total((b->>'net_minor')::numeric-(b->>'owed_minor')::numeric),'reserved_minor',b->'reserved_minor','owed_minor',b->'owed_minor','available_minor',b->'available_minor','currency','EGP','effective_at',e.effective_at)item from finance_private.tutor_earnings e join app_private.tutors t on t.id=e.tutor_id cross join lateral(select finance_private.payroll_earning_balance(e.id,p_as_of)b)v where t.account_id=actor and e.posted_at<=p_as_of and(from_at is null or e.effective_at>=from_at)and(to_at is null or e.effective_at<to_at)order by e.id limit 10001)x;
 end if;
 count_rows:=jsonb_array_length(rows);if count_rows>10000 then raise exception 'VALIDATION_ERROR';end if;
 insert into app_private.export_jobs(id,requester_id,session_id,kind,filters,columns,grain,as_of,row_count)values(eid,actor,session_id,p_kind,p_filters,p_columns,grain,p_as_of,count_rows);
 insert into app_private.export_rows(export_id,ordinal,row_data)select eid,r.ordinality,(select jsonb_object_agg(k,v)from jsonb_each(r.value)kv(k,v)where k=any(p_columns))from jsonb_array_elements(rows)with ordinality r;
 job:=app_private.enqueue_event(gen_random_uuid(),'export_requested',eid,jsonb_build_object('export_id',eid),'exports.render');insert into app_private.export_states(export_id,job_id)values(eid,job);perform set_config('response.status','202',true);
 return app_private.booking_finish(ctx,eid,1,jsonb_build_object('export_id',eid,'snapshot_at',transaction_timestamp(),'job_id',job),'export_requested',jsonb_build_object('export_id',eid));end$$;
create function app_private.export_view(p_export uuid,p_actor uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e app_private.export_jobs%rowtype;s app_private.export_states%rowtype;begin select * into e from app_private.export_jobs where id=p_export and requester_id=p_actor;if e.id is null then raise exception 'NOT_FOUND';end if;perform app_private.export_assert_scope(p_actor,e.session_id,e.kind,e.filters,e.columns);select * into s from app_private.export_states where export_id=e.id;return jsonb_build_object('export_id',e.id,'kind',e.kind,'state',s.state,'grain',e.grain,'columns',e.columns,'filters',e.filters,'snapshot_at',e.snapshot_at,'as_of',e.as_of,'row_count',e.row_count,'expires_at',e.expires_at,'version',s.version,'can_download',s.state='ready'and e.expires_at>now(),'download_path',case when s.state='ready'and e.expires_at>now()then '/api/v1/exports/'||e.id||'/content'else null end,'safe_error_code',coalesce(s.safe_error_code,(select last_error_code from app_private.outbox_jobs where id=s.job_id)));end$$;
create function api.get_export(p_export_id uuid)returns jsonb language sql security definer set search_path='' as $$select app_private.export_view(p_export_id,app_private.require_actor())$$;
create function api.list_my_exports(p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb:='[]';e record;item jsonb;begin if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;for e in select id from app_private.export_jobs where requester_id=actor and(p_cursor is null or id>p_cursor)order by id loop begin item:=app_private.export_view(e.id,actor);items:=items||jsonb_build_array(item);exception when others then if sqlerrm not in('SESSION_REVOKED','NOT_FOUND','FORBIDDEN')then raise;end if;end;exit when jsonb_array_length(items)=p_limit;end loop;return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'export_id'else null end);end$$;
create function app_private.prepare_export_render(p_export uuid,p_job uuid,p_lease uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e app_private.export_jobs%rowtype;s app_private.export_states%rowtype;begin
 if not exists(select 1 from app_private.outbox_jobs j join app_private.domain_events d on d.id=j.event_id where j.id=p_job and j.purpose='exports.render'and j.state='leased'and j.lease_token=p_lease and j.lease_expires_at>now()and d.aggregate_id=p_export and d.event_type='export_requested'and d.payload=jsonb_build_object('export_id',p_export))then raise exception 'LEASE_LOST';end if;
 select * into e from app_private.export_jobs where id=p_export;select * into s from app_private.export_states where export_id=p_export for update;if e.id is null or s.job_id<>p_job then raise exception 'NOT_FOUND';end if;
 begin perform app_private.export_assert_scope(e.requester_id,e.session_id,e.kind,e.filters,e.columns);if e.expires_at<=now()then raise exception 'NOT_FOUND';end if;exception when others then if sqlerrm not in('SESSION_REVOKED','NOT_FOUND','FORBIDDEN')then raise;end if;update app_private.export_states set state='failed',safe_error_code='FORBIDDEN',version=version+1 where export_id=e.id;return jsonb_build_object('blocked',true);end;
 if s.state<>'ready'then update app_private.export_states set state='generating',version=version+1 where export_id=e.id;end if;
 return jsonb_build_object('blocked',false,'export_id',e.id,'kind',e.kind,'columns',e.columns,'rows',(select coalesce(jsonb_agg(row_data order by ordinal),'[]'::jsonb)from app_private.export_rows where export_id=e.id),'object_key',s.object_key,'completed',s.state='ready');end$$;
create function app_private.finalize_export_render(p_export uuid,p_job uuid,p_lease uuid,p_size integer,p_hash text)returns jsonb language plpgsql security definer set search_path='' as $$declare prepared jsonb;s app_private.export_states%rowtype;begin prepared:=app_private.prepare_export_render(p_export,p_job,p_lease);if(prepared->>'blocked')::boolean then return prepared;end if;if p_size is null or p_size not between 1 and 26214400 or p_hash is null or p_hash!~'^[a-f0-9]{64}$'then raise exception 'VALIDATION_ERROR';end if;select * into s from app_private.export_states where export_id=p_export;if s.state='ready'and(s.size_bytes<>p_size or s.checksum_sha256<>p_hash)then raise exception 'VERSION_CONFLICT';end if;update app_private.export_states set state='ready',size_bytes=p_size,checksum_sha256=p_hash,safe_error_code=null,version=version+1 where export_id=p_export and state<>'ready';return jsonb_build_object('blocked',false,'export_id',p_export,'state','ready');end$$;
-- Denials return a value so their audit event commits. The trusted server converts denial to HTTP404.
create function api.authorize_export_download(p_export_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();e app_private.export_jobs%rowtype;ticket uuid;allowed boolean:=false;begin
 select * into e from app_private.export_jobs where id=p_export_id and requester_id=actor;begin if e.id is not null then perform app_private.export_assert_scope(actor,e.session_id,e.kind,e.filters,e.columns);allowed:=e.expires_at>now()and exists(select 1 from app_private.export_states where export_id=e.id and state='ready');end if;exception when others then if sqlerrm not in('SESSION_REVOKED','NOT_FOUND','FORBIDDEN')then raise;end if;end;
 insert into app_private.export_access_events(export_id,actor_id,allowed,stage)values(p_export_id,actor,allowed,'request');if not allowed then return jsonb_build_object('allowed',false);end if;
 insert into app_private.export_download_tickets(export_id,actor_id,session_id)values(e.id,actor,(current_setting('request.jwt.claims',true)::jsonb->>'session_id')::uuid)returning id into ticket;return jsonb_build_object('allowed',true,'authorization_id',ticket);end$$;
create function app_private.prepare_export_download(p_export uuid,p_ticket uuid,p_stage text)returns jsonb language plpgsql security definer set search_path='' as $$declare ticket app_private.export_download_tickets%rowtype;e app_private.export_jobs%rowtype;s app_private.export_states%rowtype;allowed boolean:=false;begin
 if p_stage not in('before_read','after_read')or p_stage is null then raise exception 'VALIDATION_ERROR';end if;select * into ticket from app_private.export_download_tickets where id=p_ticket and export_id=p_export;select * into e from app_private.export_jobs where id=p_export;select * into s from app_private.export_states where export_id=p_export;
 begin if ticket.id is not null and ticket.actor_id=e.requester_id and ticket.expires_at>now()and app_private.auth_session_active(ticket.actor_id,ticket.session_id)then perform app_private.export_assert_scope(ticket.actor_id,e.session_id,e.kind,e.filters,e.columns);allowed:=e.expires_at>now()and s.state='ready';end if;exception when others then if sqlerrm not in('SESSION_REVOKED','NOT_FOUND','FORBIDDEN')then raise;end if;end;
 insert into app_private.export_access_events(export_id,actor_id,allowed,stage)values(p_export,ticket.actor_id,allowed,p_stage);if not allowed then return jsonb_build_object('allowed',false);end if;return jsonb_build_object('allowed',true,'export_id',e.id,'object_key',s.object_key,'size_bytes',s.size_bytes,'checksum_sha256',s.checksum_sha256);end$$;
do $$declare t text;f record;begin
 foreach t in array array['crm_contact_observations','crm_identity_matches','crm_identity_reviews','export_jobs','export_rows','export_states','export_download_tickets','export_access_events']loop execute format('alter table app_private.%I enable row level security',t);execute format('create policy crm_commands_access on app_private.%I to git_tutor_commands using(true)with check(true)',t);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t);execute format('grant select,insert on app_private.%I to git_tutor_commands',t);if t in('crm_identity_matches','export_states')then execute format('grant update on app_private.%I to git_tutor_commands',t);else execute format('create trigger immutable_row before update or delete on app_private.%I for each row execute function app_private.reject_immutable_change()',t);end if;end loop;
 for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and p.proname=any(array['record_customer_contact','list_customer_contacts','list_identity_matches','review_identity_match','crm_session_dto','list_crm_sessions','export_columns','export_assert_scope','export_charge','request_export','export_view','get_export','list_my_exports','prepare_export_render','finalize_export_render','authorize_export_download','prepare_export_download'])loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);elsif f.proname in('prepare_export_render','finalize_export_render','prepare_export_download')then execute format('grant execute on function %s to git_tutor_worker',f.signature);end if;end loop;end$$;
revoke create on schema api,app_private from git_tutor_commands;
notify pgrst,'reload schema';
